// ---------------------------------------------------------------------------
// AI Configuration
// ---------------------------------------------------------------------------
//
// Reads AI provider settings from environment variables and optional CLI
// overrides. AI is enabled only when a valid API key is present AND the
// caller has not explicitly opted out with --no-ai.
//
// Environment variables:
//   OPENAI_API_KEY         — OpenAI API key (required for AI features)
//   SBI_AI_MODEL           — Chat completion model (default: gpt-4o)
//   SBI_LLM_BACKEND        — LLM backend (default: openai)
//                            Values: openai | local
//   SBI_LLM_URL            — LLM endpoint URL (default: https://api.openai.com/v1)
//                            For local backends (Ollama, llama.cpp, vLLM):
//                              http://localhost:11434/v1
//   SBI_TOKEN_BUDGET        — Max tokens of context per AI seed call (default: 100000)
//   SBI_EMBEDDING_MODEL    — Embedding model     (default: text-embedding-3-small)
//   SBI_EMBEDDING_BACKEND  — Embedding backend   (default: local)
//                            Values: local | openai | none
//   SBI_EMBEDDING_URL      — Local embedding endpoint (default: http://localhost:8080)
//                            Used when SBI_EMBEDDING_BACKEND=local

import { getRecorderMode } from './recorder.js';

export type AIProvider = 'openai' | 'none';

/**
 * Backend to use for LLM chat completions.
 *
 * - `openai` — OpenAI API (default). Requires OPENAI_API_KEY.
 * - `local`  — Any OpenAI-compatible local server (Ollama, llama.cpp,
 *              vLLM, LM Studio). Uses SBI_LLM_URL as the base endpoint.
 *              OPENAI_API_KEY can be any non-empty string (local servers
 *              typically don't validate it).
 */
export type LLMBackend = 'openai' | 'local';

/**
 * Backend to use for text embeddings.
 *
 * - `local`  — Local HTTP embedding service (TEI or Ollama). Preferred for
 *              offline / on-premise deployments. Falls back to Ollama when
 *              TEI is unavailable.
 * - `openai` — OpenAI Embeddings API (requires OPENAI_API_KEY).
 * - `none`   — Disable embeddings entirely; graph + BM25 retrieval only.
 */
export type EmbeddingBackend = 'local' | 'openai' | 'none';

export interface AIConfig {
  /** AI provider. 'none' means AI features are disabled. */
  provider: AIProvider;
  /** API key for the chosen provider. Empty string when AI is disabled. */
  apiKey: string;
  /** Chat completion model identifier. */
  model: string;
  /**
   * LLM backend to use for chat completions.
   *
   * Defaults to 'openai'. When 'local', the system connects to a local
   * OpenAI-compatible server at `llmUrl`.
   */
  llmBackend: LLMBackend;
  /**
   * Base URL for the LLM API.
   *
   * Defaults to 'https://api.openai.com/v1' for cloud, or the value of
   * SBI_LLM_URL for local backends.
   */
  llmUrl: string;
  /**
   * Maximum tokens of chunk context sent to the LLM per seed investigation.
   *
   * Defaults to 100,000 (~80% of a 128K context window). Reduce for local
   * models with smaller context windows (e.g. 20,000 for 32K models).
   */
  tokenBudget: number;
  /** Text embedding model identifier. */
  embeddingModel: string;
  /**
   * Embedding backend to use.
   *
   * Defaults to 'local' so the system prefers a locally-running embedding
   * service (TEI or Ollama) over the OpenAI API.
   */
  embeddingBackend: EmbeddingBackend;
  /**
   * Base URL for the local embedding service.
   *
   * Used when `embeddingBackend === 'local'`.  Defaults to
   * `http://localhost:8080` (HuggingFace TEI default port).
   */
  embeddingUrl: string;
  /** Whether AI features are active for this run. */
  enabled: boolean;
}

export interface LoadAIConfigOverrides {
  /** When true, disable AI features regardless of environment variables. */
  noAi?: boolean;
  /** Override the AI provider. Accepts `openai` or `none`. */
  aiProvider?: string;
}

function resolveRequestedProvider(aiProvider?: string): AIProvider {
  const normalized = aiProvider?.trim().toLowerCase();

  if (normalized === 'none') {
    return 'none';
  }

  return 'openai';
}

function resolveLLMBackend(raw: string | undefined): LLMBackend {
  const normalized = raw?.trim().toLowerCase();
  if (normalized === 'local') return 'local';
  return 'openai'; // default
}

function resolveEmbeddingBackend(raw: string | undefined): EmbeddingBackend {
  const normalized = raw?.trim().toLowerCase();
  if (normalized === 'openai') return 'openai';
  if (normalized === 'none') return 'none';
  return 'local'; // default
}

/** Default LLM base URL for OpenAI cloud. */
const OPENAI_DEFAULT_URL = 'https://api.openai.com/v1';

/** Default LLM base URL for local backends (Ollama). */
const LOCAL_LLM_DEFAULT_URL = 'http://localhost:11434/v1';

/**
 * Loads AI configuration from environment variables, applying optional
 * overrides from CLI flags.
 *
 * AI is enabled when:
 *  - `noAi` is NOT set to true, AND
 *  - The requested provider is not `none`, AND
 *  - Either:
 *    - A non-empty `OPENAI_API_KEY` env var is present (cloud mode), OR
 *    - `SBI_LLM_BACKEND=local` is set (local mode — any API key accepted,
 *      since local servers typically don't validate keys).
 */
export function loadAIConfig(overrides: LoadAIConfigOverrides = {}): AIConfig {
  const { noAi = false, aiProvider } = overrides;

  const apiKey = process.env['OPENAI_API_KEY'] ?? '';
  const model = process.env['SBI_AI_MODEL'] ?? 'gpt-4o';
  const llmBackend = resolveLLMBackend(process.env['SBI_LLM_BACKEND']);
  const embeddingModel = process.env['SBI_EMBEDDING_MODEL'] ?? 'text-embedding-3-small';
  const embeddingBackend = resolveEmbeddingBackend(process.env['SBI_EMBEDDING_BACKEND']);
  const embeddingUrl = process.env['SBI_EMBEDDING_URL'] ?? 'http://localhost:8080';
  const requestedProvider = resolveRequestedProvider(aiProvider);
  const recorderMode = getRecorderMode();

  // Resolve LLM URL: explicit env var > backend-specific default
  const llmUrlEnv = process.env['SBI_LLM_URL'] ?? '';
  const llmUrl = llmUrlEnv.trim().length > 0
    ? llmUrlEnv.trim()
    : llmBackend === 'local'
      ? LOCAL_LLM_DEFAULT_URL
      : OPENAI_DEFAULT_URL;

  // Token budget: explicit env var > default 100K
  const tokenBudgetEnv = process.env['SBI_TOKEN_BUDGET'];
  const tokenBudget = tokenBudgetEnv != null && tokenBudgetEnv.trim().length > 0
    ? Math.max(1000, parseInt(tokenBudgetEnv, 10) || 100_000)
    : 100_000;

  const hasKey = apiKey.trim().length > 0;

  // Local backends accept any API key (or a dummy key) since local servers
  // typically don't validate authentication. Cloud mode requires a real key.
  const enabled =
    requestedProvider === 'openai' &&
    !noAi &&
    (hasKey || llmBackend === 'local' || recorderMode === 'replay');

  const provider: AIProvider = enabled ? 'openai' : 'none';

  // For local backends or cassette replay without an explicit key, use a
  // placeholder so the OpenAI client constructor doesn't throw.
  const effectiveApiKey = hasKey
    ? apiKey
    : recorderMode === 'replay'
      ? 'replay'
      : llmBackend === 'local'
        ? 'local'
        : '';

  return {
    provider,
    apiKey: effectiveApiKey,
    model,
    llmBackend,
    llmUrl,
    tokenBudget,
    embeddingModel,
    embeddingBackend,
    embeddingUrl,
    enabled,
  };
}

/**
 * Returns true when AI features are active for the given config.
 *
 * Convenience wrapper so callers avoid importing the full config shape just
 * to perform a boolean check.
 */
export function isAIEnabled(config: AIConfig): boolean {
  return config.enabled;
}

import type {
  AIFindingResponse,
  InvestigationLLMClient,
  SeedAwareInvestigationLLMClient,
} from './llm-client.js';
import { cassetteSeedKey, type CassetteRecorder, getRecorderMode } from './recorder.js';

export interface SeedIdentity {
  seedId: string;
  seedCategory: string;
}

/**
 * Wraps an investigation LLM client with cassette record/replay behavior.
 *
 * - live: delegates directly to the inner client
 * - record: delegates, then stores the response keyed by current seed
 * - replay: returns cached responses only and never calls the inner client
 */
export class ReplayableLLMClient implements SeedAwareInvestigationLLMClient {
  private currentSeed: SeedIdentity | undefined;

  constructor(
    private readonly inner: InvestigationLLMClient,
    private readonly recorder: CassetteRecorder,
    private readonly seedResolver: (system: string, user: string) => SeedIdentity,
  ) {}

  setSeedContext(seedId: string, seedCategory: string): void {
    this.currentSeed = { seedId, seedCategory };
  }

  clearSeedContext(): void {
    this.currentSeed = undefined;
  }

  async investigateSeed(
    systemPrompt: string,
    userPrompt: string,
  ): Promise<AIFindingResponse> {
    const seed = this.currentSeed ?? this.seedResolver(systemPrompt, userPrompt);

    if (this.recorder.mode === 'replay') {
      const cassette = this.recorder.replay(seed.seedId, seed.seedCategory);
      if (cassette !== undefined) {
        return {
          findings: cassette.response.findings,
          rawResponse: cassette.response.rawResponse,
        };
      }

      console.warn(
        `[ReplayableLLMClient] Missing cassette for ${cassetteSeedKey(seed.seedId, seed.seedCategory)} (${seed.seedId}, ${seed.seedCategory})`,
      );
      return { findings: [], rawResponse: undefined };
    }

    const response = await this.inner.investigateSeed(systemPrompt, userPrompt);

    if (this.recorder.mode === 'record') {
      this.recorder.record(
        seed.seedId,
        seed.seedCategory,
        { system: systemPrompt, user: userPrompt },
        { findings: response.findings, rawResponse: response.rawResponse ?? '' },
        getInnerModel(this.inner),
      );
    }

    return response;
  }

  async generateText(systemPrompt: string, userPrompt: string): Promise<string> {
    if (this.recorder.mode === 'replay') {
      return '';
    }
    return this.inner.generateText(systemPrompt, userPrompt);
  }
}

function getInnerModel(client: InvestigationLLMClient): string {
  const withModel = client as InvestigationLLMClient & { model?: string };
  if (typeof withModel.model === 'string') {
    return withModel.model;
  }

  const candidate = client as InvestigationLLMClient & { getModel?: () => string };
  if (typeof candidate.getModel === 'function') {
    return candidate.getModel();
  }

  return 'unknown';
}

/**
 * Default seed resolver used as a fallback when no explicit seed context was
 * provided. The AI investigator sets seed context directly, so this path is
 * only a safety net.
 */
export function defaultSeedResolver(systemPrompt: string, userPrompt: string): SeedIdentity {
  const combined = `${systemPrompt}\n${userPrompt}`;
  const mode = getRecorderMode();
  return {
    seedId: `unresolved:${mode}:${combined.length}`,
    seedCategory: 'unknown',
  };
}

// ---------------------------------------------------------------------------
// LLM Client
// ---------------------------------------------------------------------------
//
// Thin wrapper around the OpenAI chat completions API for structured AI
// investigations.
//
// Design principles:
// - Never throws — all API/network/parse errors are caught, logged with
//   console.warn, and returned as empty findings arrays.
// - Uses JSON mode (response_format: { type: 'json_object' }) to ensure
//   the model returns valid JSON that can be parsed and validated.
// - Validates the parsed response through `validateAIFindings` before
//   returning — invalid findings are dropped, not thrown.

import OpenAI from 'openai';
import type { AIConfig } from './config.js';
import type { AIFinding } from './schemas.js';
import { validateAIFindings } from './schemas.js';
import type { HydeLLMClient } from './hyde.js';

// ---------------------------------------------------------------------------
// AIFindingResponse
// ---------------------------------------------------------------------------

/**
 * The response produced by a single LLM investigation call.
 *
 * On API failure, `findings` is empty and `rawResponse` is absent.
 * On JSON parse failure, `findings` is empty and `rawResponse` holds the
 * unparseable string for debugging.
 */
export interface AIFindingResponse {
  /** Validated, sanitised findings. Empty when the call fails or returns nothing useful. */
  findings: AIFinding[];
  /** Raw JSON string returned by the model (present even on validation failure). */
  rawResponse?: string;
}

/**
 * Shared interface for AI investigation clients.
 *
 * Implemented by the real {@link LLMClient} and by wrappers such as
 * `ReplayableLLMClient` that intercept investigation calls.
 */
export interface InvestigationLLMClient extends HydeLLMClient {
  investigateSeed(
    systemPrompt: string,
    userPrompt: string,
  ): Promise<AIFindingResponse>;
}

/**
 * Optional extension point for clients that need to know which seed is about
 * to be investigated before `investigateSeed()` is called.
 */
export interface SeedAwareInvestigationLLMClient extends InvestigationLLMClient {
  setSeedContext(seedId: string, seedCategory: string): void;
  clearSeedContext?(): void;
}

// ---------------------------------------------------------------------------
// LLMClient
// ---------------------------------------------------------------------------

/**
 * Wraps the OpenAI chat completions API for structured K8s investigation.
 *
 * Implements {@link HydeLLMClient} so it can be passed directly to
 * `generateHypotheticalDocument` without any adapter.
 *
 * Instantiate with a loaded {@link AIConfig} (must have `enabled: true` and a
 * valid `apiKey`). If the config is disabled, callers should not construct
 * this class — use the `isAIEnabled` guard from `config.ts` first.
 *
 * Supports both cloud (OpenAI) and local (Ollama, llama.cpp, vLLM, LM Studio)
 * backends via the `llmUrl` config field. Local backends use an OpenAI-
 * compatible API, so the same client works for both.
 */
export class LLMClient implements InvestigationLLMClient {
  private readonly client: OpenAI;
  private readonly model: string;

  constructor(config: AIConfig) {
    this.client = new OpenAI({
      apiKey: config.apiKey,
      baseURL: config.llmUrl,
    });
    this.model = config.model;
  }

  getModel(): string {
    return this.model;
  }

  /**
   * Generates free-form text given a system and user prompt.
   *
   * Unlike `investigateSeed`, this method does NOT use JSON mode — the model
   * response is returned as a plain string.
   *
   * **Does not swallow errors** — throws on network/API failure so that
   * callers (e.g. `generateHypotheticalDocument`) can detect failure and apply
   * their own fallback logic.
   *
   * @param systemPrompt - System-level context for the generation task.
   * @param userPrompt   - User-facing prompt.
   * @returns Generated text string.  Empty string if the model returns no content.
   */
  async generateText(systemPrompt: string, userPrompt: string): Promise<string> {
    const response = await this.client.chat.completions.create({
      model: this.model,
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: userPrompt },
      ],
    });

    return response.choices[0]?.message?.content ?? '';
  }

  /**
   * Calls the LLM with a system + user prompt pair and returns structured
   * findings.
   *
   * Uses `response_format: { type: 'json_object' }` so the model always
   * returns a JSON object. The response is parsed and validated through
   * {@link validateAIFindings} before being returned.
   *
   * **Graceful degradation**: any error (network, API, JSON parse, validation)
   * is caught and logged via `console.warn`. The method always resolves, never
   * rejects.
   *
   * @param systemPrompt - System prompt with grounding rules and playbook.
   * @param userPrompt   - User prompt with hypothesis, chunks, and schema.
   * @returns AIFindingResponse — validated findings + optional raw response.
   */
  async investigateSeed(
    systemPrompt: string,
    userPrompt: string,
  ): Promise<AIFindingResponse> {
    let rawResponse: string | undefined;

    try {
      const response = await this.client.chat.completions.create({
        model: this.model,
        response_format: { type: 'json_object' },
        messages: [
          { role: 'system', content: systemPrompt },
          { role: 'user', content: userPrompt },
        ],
      });

      rawResponse = response.choices[0]?.message?.content ?? '{}';

      let parsed: unknown;
      try {
        parsed = JSON.parse(rawResponse);
      } catch (parseError) {
        console.warn(
          `[LLMClient] Failed to parse JSON response: ${parseError instanceof Error ? parseError.message : String(parseError)}`,
        );
        return { findings: [], rawResponse };
      }

      // Extract the `findings` array from the parsed JSON object
      const rawFindings =
        parsed !== null &&
        typeof parsed === 'object' &&
        !Array.isArray(parsed) &&
        'findings' in parsed
          ? (parsed as Record<string, unknown>)['findings']
          : [];

      const findings = validateAIFindings(rawFindings);

      return { findings, rawResponse };
    } catch (error) {
      console.warn(
        `[LLMClient] API call failed: ${error instanceof Error ? error.message : String(error)}`,
      );
      return { findings: [] };
    }
  }
}

// ---------------------------------------------------------------------------
// AI Investigator
// ---------------------------------------------------------------------------
//
// Implements an AI-powered investigation flow that augments the heuristic
// pipeline with graph traversal and lexical retrieval.
//
// Design principles:
// - Graph-first: `getRelatedChunks` provides the deterministic precision floor.
// - Lexical expansion: `LexicalSearchIndex.search` adds supplementary evidence.
// - Grounded findings: every AI finding must cite evidence from provided chunks.
// - Graceful degradation: LLM errors are caught and logged; the pipeline
//   continues with remaining seeds rather than aborting.
// - Category-specific playbooks: each seed's category routes to the right
//   investigation playbook via `buildInvestigationPrompt`.

import type { Finding, Evidence, GraphEdge } from '../types/index.js';
import type { InvestigatorContext, InvestigatorResult, InvestigationSeed } from './types.js';
import type {
  InvestigationLLMClient,
  SeedAwareInvestigationLLMClient,
} from '../ai/llm-client.js';
import type { IndexedChunk } from '../ai/chunk-indexer.js';
import type { ResourceRelationshipGraph } from '../graph/resource-graph.js';
import type { LexicalSearchIndex } from '../ai/lexical-search.js';
import type { AIFinding, AIFindingEvidence } from '../ai/schemas.js';
import type { EmbeddingClientInterface } from '../ai/embeddings.js';
import type { VectorStore } from '../ai/vector-store.js';
import type { DiagnosticGraph } from '../graph/diagnostic-graph.js';
import { validateAIFindings } from '../ai/schemas.js';
import { getRelatedChunks } from '../graph/resource-graph.js';
import type { GraphScoredChunk } from '../graph/resource-graph.js';
import { traverseForChunks, RETRIEVAL_EDGE_TYPES, isDiagnosticGraph } from '../graph/traversal.js';
import { buildInvestigationPrompt } from '../ai/prompts.js';
import { estimateTokens } from '../ai/chunk-indexer.js';
import { generateHypotheticalDocument } from '../ai/hyde.js';

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

/** Maximum number of seeds to investigate per AI invocation (configurable). */
export const DEFAULT_MAX_SEEDS = 10;

/**
 * Maximum number of chunks sent to the LLM per seed call.
 *
