        resourceGraph,
        diagnosticGraph,
        lexicalIndex,
        llmClient,
        tokenBudget: aiConfig.tokenBudget,
        verbose,
        ...(embeddingClient !== undefined && vectorStore !== undefined
          ? { embeddingClient, vectorStore }
          : {}),
      };

      completeTraceStep(trace, stepAI, chunks.length);
      emitProgress(options, { step: 'ai-index', status: 'completed', artifactsProcessed: chunks.length });
      log(`AI index built: ${chunks.length} chunks`, verbose);
    } catch (error) {
      // Graceful degradation: AI setup failed, continue without AI
      const errorMessage = error instanceof Error ? error.message : String(error);
      console.warn(
        `[pipeline] AI index build failed, continuing in heuristic-only mode: ` +
          errorMessage,
      );
      completeTraceStep(trace, stepAI, 0, [errorMessage]);
      emitProgress(options, { step: 'ai-index', status: 'completed', artifactsProcessed: 0 });
    }
  }

  // ── 8. Build investigation graph ──────────────────────────────────────────
  const step7 = startTraceStep(trace, 'build-graph');
  emitProgress(options, { step: 'build-graph', status: 'started' });
  log('Building investigation graph…', verbose);

  const graph = new InvestigationGraphImpl();
  let graphNodeCount = 0;

  for (const result of analyzerResults) {
    graph.addNode({
      id: `analyzer:${result.name}`,
      type: 'evidence',
      data: result,
      metadata: { category: 'analyzer' },
    });
    graphNodeCount++;
  }

  for (const resource of resources) {
    const nodeId = `resource:${resource.kind}/${resource.metadata.namespace ?? '_'}/${resource.metadata.name}`;
    graph.addNode({
      id: nodeId,
      type: 'artifact',
      data: resource,
      metadata: { category: 'kubernetes-resource' },
    });
    graphNodeCount++;
  }

  for (let i = 0; i < events.length; i++) {
    const event = events[i]!;
    const nodeId = `event:${i}:${event.reason}:${event.involvedObject.name}`;
    graph.addNode({
      id: nodeId,
      type: 'evidence',
      data: event,
      metadata: { category: 'event' },
    });
    graphNodeCount++;
  }

  for (const logFile of logs) {
    const nodeId = `log:${logFile.path}`;
    graph.addNode({
      id: nodeId,
      type: 'artifact',
      data: logFile,
      metadata: { category: 'log' },
    });
    graphNodeCount++;
  }

  completeTraceStep(trace, step7, graphNodeCount);
  emitProgress(options, { step: 'build-graph', status: 'completed', artifactsProcessed: graphNodeCount });
  log(`Built graph with ${graphNodeCount} nodes`, verbose);

  // ── 9. Run investigation pipeline ────────────────────────────────────────
  const step8 = startTraceStep(trace, 'investigate');
  emitProgress(options, { step: 'investigate', status: 'started' });
  log('Running investigation pipeline…', verbose);

  // Build a seed-level progress reporter so the TUI can show per-seed updates
  const seedProgress = options.onProgress
    ? (seedIndex: number, seedTotal: number, seedLabel: string) => {
        emitProgress(options, {
          step: 'investigate',
          status: 'started',
          detail: `Seed ${seedIndex}/${seedTotal}: ${seedLabel}`,
        });
      }
    : undefined;

  let investigationResult: Awaited<ReturnType<typeof runInvestigation>>;
  try {
    investigationResult = await runInvestigation(
      {
        analyzerResults,
        resources,
        events,
        logs,
        profile,
        resourceSourceFiles,
        helmReleases,
      },
      aiDeps,
      seedProgress,
    );
  } finally {
    if (cassetteRecorder?.mode === 'record') {
      await cassetteRecorder.flush();
    }
  }

  const evidenceNodeCount = addInvestigationEvidenceNodes(
    graph,
    investigationResult.findings,
  );

  // Add finding nodes to the investigation graph.
  for (const finding of investigationResult.findings) {
    graph.addNode({
      id: finding.id,
      type: 'finding',
      data: finding,
      metadata: {
        severity: finding.severity,
        confidence: finding.confidence,
      },
    });
  }

  const derivedEvidenceNodeCount = ensureInvestigationEdgeEndpoints(
    graph,
    investigationResult.findings,
    investigationResult.edges,
  );

  // Add graph edges discovered by investigators.
  for (const edge of investigationResult.edges) {
    graph.addEdge(edge);
  }

  const investigateArtifactsProcessed =
    evidenceNodeCount +
    derivedEvidenceNodeCount +
    investigationResult.findings.length +
    investigationResult.edges.length;
  completeTraceStep(trace, step8, investigateArtifactsProcessed);
  emitProgress(options, { step: 'investigate', status: 'completed', artifactsProcessed: investigateArtifactsProcessed });
  const aiSuffix = investigationResult.metadata.aiEnabled
    ? `, ${investigationResult.metadata.aiFindings} AI findings`
    : '';
  log(
    `Investigation: ${investigationResult.metadata.seedCount} seeds, ` +
      `${investigationResult.metadata.rawFindingCount} raw findings → ` +
      `${investigationResult.metadata.finalFindingCount} after verification, ` +
      `${evidenceNodeCount + derivedEvidenceNodeCount} evidence nodes, ` +
      `${investigationResult.edges.length} edges${aiSuffix}`,

[60 more lines in file. Use offset=681 to continue.]

    verbose,
  );

  // ── 10. Complete trace ────────────────────────────────────────────────────
  completeTrace(trace, profile);

  // Derive AI mode label for TUI / reports
  const aiMode: AIMode = !aiConfig.enabled
    ? 'off'
    : aiConfig.llmBackend === 'local'
      ? 'local'
      : 'cloud';

  return {
    profile,
    analyzerResults,
    resources,
    events,
    logs,
    findings: investigationResult.findings,
    findingTree: investigationResult.findingTree,
    graph,
    trace,
    aiMode,
  };
}

// ---------------------------------------------------------------------------
// Cleanup helper
// ---------------------------------------------------------------------------

/**
 * Removes the temporary extraction directory created by the pipeline.
 *
 * Only removes directories that appear to be auto-created temp dirs (i.e.
 * paths under `os.tmpdir()` matching the `sbi-bundle-*` pattern). Caller is
 * responsible for deciding whether to clean up.
 */
export async function cleanupPipelineResult(result: PipelineResult): Promise<void> {
  const extractedPath = path.resolve(result.profile.manifest.extractedPath);
  const tempRoot = path.resolve(os.tmpdir());
  const relativeToTempRoot = path.relative(tempRoot, extractedPath);

  const isAutoCreatedTempDir =
    relativeToTempRoot !== '' &&
    !relativeToTempRoot.startsWith('..') &&
    !path.isAbsolute(relativeToTempRoot) &&
    path.basename(extractedPath).startsWith('sbi-bundle-');

  if (!isAutoCreatedTempDir) {
    return;
  }

  try {
    await fsp.rm(extractedPath, { recursive: true, force: true });
  } catch {
    // Silently ignore cleanup failures
  }
}

// ---------------------------------------------------------------------------
// LLM Response Recorder / Replay
// ---------------------------------------------------------------------------
//
// Provides record/replay for LLM investigation calls so nightly CI can
// capture real API responses and PR CI can replay them deterministically.
//
// Mode is controlled via `SBI_AI_MODE` environment variable:
//   - `live`   — real API calls, no recording (default)
//   - `record` — real API calls, save cassettes to disk
//   - `replay` — load cassettes, match by seed key, return cached response
//
// Cassettes are keyed by a hash of seed.id + seed.category so that prompt
// refactoring does not invalidate recordings. If a seed has no matching
// cassette during replay, the call returns empty findings (not an error).

import * as fsp from 'fs/promises';
import * as path from 'path';
import * as crypto from 'crypto';
import type { AIFinding } from './schemas.js';

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export type RecorderMode = 'live' | 'record' | 'replay';

export interface Cassette {
  seedKey: string;
  seedId: string;
  seedCategory: string;
  request: { system: string; user: string };
  response: { findings: AIFinding[]; rawResponse: string };
  model: string;
  timestamp: string;
}

export interface CassetteStore {
  version: string;
  cassettes: Record<string, Cassette>;
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/**
 * Computes a stable cassette key from a seed's identity fields.
 *
 * Uses `seed.id + seed.category` so that prompt text changes don't
 * invalidate recordings — only seed identity matters.
 */
export function cassetteSeedKey(seedId: string, seedCategory: string): string {
  const hash = crypto
    .createHash('sha256')
    .update(`${seedId}::${seedCategory}`)
    .digest('hex')
    .slice(0, 16);
  return `${seedCategory}:${hash}`;
}

/**
 * Reads the `SBI_AI_MODE` environment variable and normalises it to a
 * valid {@link RecorderMode}. Defaults to `'live'`.
 */
export function getRecorderMode(): RecorderMode {
  const raw = (process.env['SBI_AI_MODE'] ?? 'live').trim().toLowerCase();
  if (raw === 'record' || raw === 'replay') return raw;
  return 'live';
}

// ---------------------------------------------------------------------------
// CassetteRecorder
// ---------------------------------------------------------------------------

/**
 * Records and replays LLM investigation call responses.
 *
 * ### Recording flow (nightly CI)
 * ```typescript
 * const recorder = new CassetteRecorder('record', './test/cassettes');
 * // After each real LLM call:
 * recorder.record(seedId, seedCategory, request, response, model);
 * // At the end:
 * await recorder.flush();
 * ```
 *
 * ### Replay flow (PR CI)
 * ```typescript
 * const recorder = new CassetteRecorder('replay', './test/cassettes');
 * await recorder.load();
 * // Instead of calling the LLM:
 * const cached = recorder.replay(seedId, seedCategory);
 * if (cached) { use cached.response } else { skip or warn }
 * ```
 */
export class CassetteRecorder {
  readonly mode: RecorderMode;
  private readonly dir: string;
  private store: CassetteStore;

  constructor(mode: RecorderMode, cassetteDir: string) {
    this.mode = mode;
    this.dir = cassetteDir;
    this.store = { version: '1', cassettes: {} };
  }

  /** Returns the file path for the consolidated cassette store. */
  get storePath(): string {
    return path.join(this.dir, 'cassettes.json');
  }

  /** Number of cassettes currently held in memory. */
  get size(): number {
    return Object.keys(this.store.cassettes).length;
  }

  /**
   * Records a single LLM call.
   *
   * Only takes effect in `record` mode; no-ops in other modes.
   */
  record(
    seedId: string,
    seedCategory: string,
    request: { system: string; user: string },
    response: { findings: AIFinding[]; rawResponse: string },
    model: string,
  ): void {
    if (this.mode !== 'record') return;

    const key = cassetteSeedKey(seedId, seedCategory);
    this.store.cassettes[key] = {
      seedKey: key,
      seedId,
      seedCategory,
      request,
      response,
      model,
      timestamp: new Date().toISOString(),
    };
  }

  /**
   * Retrieves a cached response for the given seed identity.
   *
   * Returns `undefined` when no matching cassette exists.
   */
  replay(
    seedId: string,
    seedCategory: string,
  ): Cassette | undefined {
    const key = cassetteSeedKey(seedId, seedCategory);
    return this.store.cassettes[key];
  }

  /**
   * Loads cassettes from disk into memory.
   *
   * Safe to call in any mode — silently returns if the file doesn't exist.
   */
  async load(): Promise<void> {
    try {
      const raw = await fsp.readFile(this.storePath, 'utf-8');
      const parsed = JSON.parse(raw) as CassetteStore;
      if (parsed.version === '1' && typeof parsed.cassettes === 'object') {
        this.store = parsed;
      }
    } catch {
      // File not found or parse error — start with empty store
      this.store = { version: '1', cassettes: {} };
    }
  }

  /**
   * Writes all recorded cassettes to disk.
   *
   * Only takes effect in `record` mode; no-ops in other modes.
   */
  async flush(): Promise<void> {
    if (this.mode !== 'record') return;

    await fsp.mkdir(this.dir, { recursive: true });
    await fsp.writeFile(
      this.storePath,
      JSON.stringify(this.store, null, 2),
      'utf-8',
    );
  }

  /** Returns all stored cassette keys (for diagnostics). */
  keys(): string[] {
    return Object.keys(this.store.cassettes);
  }

  /** Checks if a cassette exists for the given seed. */
  has(seedId: string, seedCategory: string): boolean {
    return this.replay(seedId, seedCategory) !== undefined;
  }
}

import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';

import { CassetteRecorder, cassetteSeedKey } from '../recorder.js';
import { ReplayableLLMClient } from '../replayable-llm-client.js';
import type { InvestigationLLMClient } from '../llm-client.js';

const VALID_FINDING = {
  title: 'CrashLoopBackOff: Pod app-pod',
  severity: 'critical' as const,
  confidence: 0.9,
  affectedComponents: ['Pod/default/app-pod'],
  reasoningSummary: 'Pod app-pod is restarting repeatedly.',
  evidence: [{ path: 'cluster-resources/pods/default/app-pod.yaml', note: 'CrashLoopBackOff' }],
  contradictionsChecked: [],
  recommendedAction: 'Inspect logs.',
  missingEvidence: [],
};

function makeInnerClient() {
  return {
    investigateSeed: vi.fn().mockResolvedValue({
      findings: [VALID_FINDING],
      rawResponse: JSON.stringify({ findings: [VALID_FINDING] }),
    }),
    generateText: vi.fn().mockResolvedValue('generated text'),
    getModel: vi.fn().mockReturnValue('gpt-4o'),
  } satisfies InvestigationLLMClient & { getModel: () => string };
}

let tmpDir: string;

beforeEach(() => {
  tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'sbi-replayable-'));
});

afterEach(() => {
  fs.rmSync(tmpDir, { recursive: true, force: true });
  vi.restoreAllMocks();
});

describe('ReplayableLLMClient', () => {
  it('records responses in record mode and delegates to the inner client', async () => {
    const inner = makeInnerClient();
    const recorder = new CassetteRecorder('record', tmpDir);
    const client = new ReplayableLLMClient(inner, recorder, () => ({
      seedId: 'fallback-seed',
      seedCategory: 'kubernetes',
    }));

    client.setSeedContext('seed:k8s:0', 'kubernetes');
    const result = await client.investigateSeed('system prompt', 'user prompt');

    expect(inner.investigateSeed).toHaveBeenCalledWith('system prompt', 'user prompt');
    expect(result.findings).toHaveLength(1);
    expect(recorder.has('seed:k8s:0', 'kubernetes')).toBe(true);

    const cassette = recorder.replay('seed:k8s:0', 'kubernetes');
    expect(cassette?.seedKey).toBe(cassetteSeedKey('seed:k8s:0', 'kubernetes'));
    expect(cassette?.response.findings[0]?.title).toBe(VALID_FINDING.title);
    expect(cassette?.model).toBe('gpt-4o');
  });

  it('replays cached responses without calling the inner client', async () => {
    const recordRecorder = new CassetteRecorder('record', tmpDir);
    recordRecorder.record(
      'seed:k8s:1',
      'kubernetes',
      { system: 'system prompt', user: 'user prompt' },
      { findings: [VALID_FINDING], rawResponse: JSON.stringify({ findings: [VALID_FINDING] }) },
      'gpt-4o',
    );
    await recordRecorder.flush();

    const replayRecorder = new CassetteRecorder('replay', tmpDir);
    await replayRecorder.load();

    const inner = makeInnerClient();
    const client = new ReplayableLLMClient(inner, replayRecorder, () => ({
      seedId: 'seed:k8s:1',
      seedCategory: 'kubernetes',
    }));

    client.setSeedContext('seed:k8s:1', 'kubernetes');
    const result = await client.investigateSeed('system prompt', 'user prompt');

    expect(result.findings).toHaveLength(1);
    expect(result.rawResponse).toContain('CrashLoopBackOff');
    expect(inner.investigateSeed).not.toHaveBeenCalled();
  });

  it('degrades gracefully for missing replay cassettes and warns', async () => {
    const warnSpy = vi.spyOn(console, 'warn').mockImplementation(() => undefined);
    const recorder = new CassetteRecorder('replay', tmpDir);
    await recorder.load();

    const inner = makeInnerClient();
    const client = new ReplayableLLMClient(inner, recorder, () => ({
      seedId: 'seed:k8s:missing',
      seedCategory: 'kubernetes',
    }));

    client.setSeedContext('seed:k8s:missing', 'kubernetes');
    const result = await client.investigateSeed('system prompt', 'user prompt');

    expect(result).toEqual({ findings: [], rawResponse: undefined });
    expect(inner.investigateSeed).not.toHaveBeenCalled();
    expect(warnSpy).toHaveBeenCalledWith(
      expect.stringContaining(cassetteSeedKey('seed:k8s:missing', 'kubernetes')),
    );
  });

  it('passes through unchanged in live mode', async () => {
    const inner = makeInnerClient();
    const recorder = new CassetteRecorder('live', tmpDir);
    const client = new ReplayableLLMClient(inner, recorder, () => ({
      seedId: 'seed:k8s:2',
      seedCategory: 'kubernetes',
    }));

    const result = await client.investigateSeed('system prompt', 'user prompt');

    expect(result.findings).toHaveLength(1);
    expect(inner.investigateSeed).toHaveBeenCalledTimes(1);
    expect(recorder.size).toBe(0);
  });

  it('returns an empty string for generateText in replay mode', async () => {
    const inner = makeInnerClient();
    const recorder = new CassetteRecorder('replay', tmpDir);
    const client = new ReplayableLLMClient(inner, recorder, () => ({
      seedId: 'seed:k8s:3',
      seedCategory: 'kubernetes',
    }));

    await expect(client.generateText('system prompt', 'user prompt')).resolves.toBe('');
    expect(inner.generateText).not.toHaveBeenCalled();
  });

  it('delegates generateText in record and live modes', async () => {
    const recordInner = makeInnerClient();
    const recordClient = new ReplayableLLMClient(
      recordInner,
      new CassetteRecorder('record', tmpDir),
      () => ({ seedId: 'seed:k8s:4', seedCategory: 'kubernetes' }),
    );
    await expect(recordClient.generateText('system prompt', 'user prompt')).resolves.toBe('generated text');
    expect(recordInner.generateText).toHaveBeenCalledWith('system prompt', 'user prompt');

    const liveInner = makeInnerClient();
    const liveClient = new ReplayableLLMClient(
      liveInner,
      new CassetteRecorder('live', tmpDir),
      () => ({ seedId: 'seed:k8s:5', seedCategory: 'kubernetes' }),
    );
    await expect(liveClient.generateText('system prompt', 'user prompt')).resolves.toBe('generated text');
    expect(liveInner.generateText).toHaveBeenCalledWith('system prompt', 'user prompt');
  });
});

