// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/** Saves and restores specific env vars around a test. */
function withEnv(
  vars: Record<string, string | undefined>,
  fn: () => void,
): void {
  const managedVars: Record<string, string | undefined> = {
    SBI_AI_MODE: undefined,
    ...vars,
  };
  const originals: Record<string, string | undefined> = {};
  for (const key of Object.keys(managedVars)) {
    originals[key] = process.env[key];
  }
  try {
    for (const [key, value] of Object.entries(managedVars)) {
      if (value === undefined) {
        delete process.env[key];
      } else {
        process.env[key] = value;
      }
    }
    fn();
  } finally {
    for (const [key, orig] of Object.entries(originals)) {
      if (orig === undefined) {
        delete process.env[key];
      } else {
        process.env[key] = orig;
      }
    }
  }
}

