 * raw retrieval scores (hop-distance, BM25, cosine similarity), but is not used
 * by `mergeChunks` itself — rank within the list is what counts for RRF.
 */
export interface RetrievalList {
  chunks: IndexedChunk[];
  scores?: number[];
