    // Should NOT throw
    await expect(
      analyzeBundlePipeline('/fake/bundle.tar.gz'),
    ).resolves.not.toThrow();

    // AI setup failed → no aiDeps passed
    expect(runInvestigation).toHaveBeenCalled();
    expect(vi.mocked(runInvestigation).mock.calls[0]?.[1]).toBeUndefined();

    warnSpy.mockRestore();
  });

