    Mi: 1024 ** 2,
    Gi: 1024 ** 3,
    Ti: 1024 ** 4,
    Pi: 1024 ** 5,
  };

  const multiplier = multipliers[unit];
  if (multiplier == null) return undefined;
  return amount * multiplier;
